def extract_min_max(test_tup, K):
    """Write a function to extract maximum and minimum k elements in the given tuple."""
    if K <= 0:
        return ()
    sorted_vals = sorted(test_tup)
    if 2 * K >= len(sorted_vals):
        return tuple(sorted_vals)
    return tuple(sorted_vals[:K] + sorted_vals[-K:])
